INSERT INTO sys_role (
    role_code, role_name, status, remark, created_at, updated_at, deleted
) VALUES (
    #{roleCode}, #{roleName}, #{status}, #{remark}, NOW(), NOW(), 0
)

INSERT IGNORE INTO sys_role_menu (
    role_id, menu_id, created_at
) VALUES (
    #{roleId}, #{menuId}, NOW()
)
